-- Manager Futebol Online: clubes ficticios controlados pelo computador
-- Cria 20 clubes por país (10 por divisão), total de 200 clubes.
-- Execute uma vez no Supabase SQL Editor. Seguro para executar novamente.
alter table public.clubs alter column owner_id drop not null;
alter table public.clubs add column if not exists is_ai boolean not null default false;
alter table public.clubs add column if not exists league_id uuid references public.leagues(id);

insert into public.clubs (owner_id, nome, sigla, cidade, pais, estadio, capacidade, orcamento, is_ai, league_id)
