from (values
(NULL::uuid, 'Aurora FC', 'AUR', 'Caçapava', 'Brasil', 'Estádio Aurora FC', 10000, 5000000, true, (select id from public.leagues where pais='Brasil' and nome='Liga Nacional' and divisao='1ª divisão' and temporada=1 limit 1)),
