(NULL::uuid, 'Pumas del Bajío', 'PUM', 'Oaxaca', 'México', 'Estádio Pumas del Bajío', 10000, 5000000, true, (select id from public.leagues where pais='México' and nome='Liga de Expansión MX' and divisao='2ª divisão' and temporada=1 limit 1)),
