(NULL::uuid, 'Club del Desierto', 'CLU', 'Toluca', 'México', 'Estádio Club del Desierto', 10000, 5000000, true, (select id from public.leagues where pais='México' and nome='Liga de Expansión MX' and divisao='2ª divisão' and temporada=1 limit 1)),
(NULL::uuid, 'Deportivo Hidalgo', 'DEP', 'Querétaro', 'México', 'Estádio Deportivo Hidalgo', 10000, 5000000, true, (select id from public.leagues where pais='México' and nome='Liga de Expansión MX' and divisao='2ª divisão' and temporada=1 limit 1)),
