) as v(owner_id,nome,sigla,cidade,pais,estadio,capacidade,orcamento,is_ai,league_id)
where v.league_id is not null
and not exists (select 1 from public.clubs c where c.nome=v.nome and c.pais=v.pais);

select pais, count(*) as clubes
from public.clubs where is_ai = true
group by pais order by pais;